-- Read-only preflight for the TOTO after-sales menu. This script performs no writes.
SELECT m.id,m.code,m.name,m.path,p.code AS parent_code,m.category_code,m.enable,m.is_hide,m.ordinal,COUNT(DISTINCT rm.role_id) AS role_bindings,COUNT(DISTINCT mo.id) AS operation_count
FROM sys_module m
LEFT JOIN sys_module p ON p.id=m.parent_id
LEFT JOIN sys_role_module rm ON rm.module_id=m.id
LEFT JOIN sys_module_operation mo ON mo.module_id=m.id
WHERE m.code IN ('afterSales','afsDashboard','afsCustomerService','afsCustomer','afsNetwork','afsCatalog','afsServiceResource','afsInventory','afsAntiDiversion','afsMemberOperation','afsDataCenter','afsDownloadCenter','afsDashboardOverview','afsDashboardCustomerService','afsDashboardStation','afsDashboardDealer','afsServiceIntake','afsWorkOrder','afsDispatch','afsDispatchPolicy','afsWorkOrderAssignment','afsPersonnelAssignmentPolicy','afsWorkOrderException','afsCompletionReview','afsFollowUp','afsKnowledgeBase','afsComplaint','afsSettlement','afsCustomerArchive','afsAppointment','afsDealerRegistration','afsDealerCustomer','afsDealer','afsStore','afsServiceStation','afsServiceArea','afsProductCategory','afsProduct','afsProductSeries','afsPart','afsRealtimeWorkOrder','afsServicePersonnel','afsSchedule','afsServiceQuality','afsPartInbound','afsPartStock','afsPartRequisition','afsPartReturn','afsPartTransfer','afsPartConsumption','afsStocktake','afsInstallationCode','afsDiversionSearch','afsBarcodeException','afsDiversionReview','afsDiversionRule','afsMember','afsMemberTag','afsMemberPush','afsServiceSurvey','afsProductSurvey','afsReport','afsDictionary','afsDataJob','afsDownloadTask','afsDownloadTemplate','afsDownloadScene','afsConsumerSupportConfig','afsNavigationAdministrator','afsWorkspaceHeadquarters','afsWorkspaceServiceDesk','afsWorkspaceStation','afsWorkspaceDealer','afsDealerAppointment','afsDecorationCompany','afsServiceItem','afsProductBundle','afsDealerStoreContext','afsDealerCustomerInput','afsDealerPrivacyConsent')
GROUP BY m.id,m.code,m.name,m.path,p.code,m.category_code,m.enable,m.is_hide,m.ordinal
ORDER BY m.code;

SELECT mo.id,m.code AS module_code,mo.code AS operation_code,mo.name,mo.enable,mo.api_list,COUNT(DISTINCT ro.role_id) AS role_bindings
FROM sys_module_operation mo
JOIN sys_module m ON m.id=mo.module_id
LEFT JOIN sys_role_operation ro ON ro.operation_id=mo.id
WHERE m.code IN ('afterSales','afsDashboard','afsCustomerService','afsCustomer','afsNetwork','afsCatalog','afsServiceResource','afsInventory','afsAntiDiversion','afsMemberOperation','afsDataCenter','afsDownloadCenter','afsDashboardOverview','afsDashboardCustomerService','afsDashboardStation','afsDashboardDealer','afsServiceIntake','afsWorkOrder','afsDispatch','afsDispatchPolicy','afsWorkOrderAssignment','afsPersonnelAssignmentPolicy','afsWorkOrderException','afsCompletionReview','afsFollowUp','afsKnowledgeBase','afsComplaint','afsSettlement','afsCustomerArchive','afsAppointment','afsDealerRegistration','afsDealerCustomer','afsDealer','afsStore','afsServiceStation','afsServiceArea','afsProductCategory','afsProduct','afsProductSeries','afsPart','afsRealtimeWorkOrder','afsServicePersonnel','afsSchedule','afsServiceQuality','afsPartInbound','afsPartStock','afsPartRequisition','afsPartReturn','afsPartTransfer','afsPartConsumption','afsStocktake','afsInstallationCode','afsDiversionSearch','afsBarcodeException','afsDiversionReview','afsDiversionRule','afsMember','afsMemberTag','afsMemberPush','afsServiceSurvey','afsProductSurvey','afsReport','afsDictionary','afsDataJob','afsDownloadTask','afsDownloadTemplate','afsDownloadScene','afsConsumerSupportConfig','afsNavigationAdministrator','afsWorkspaceHeadquarters','afsWorkspaceServiceDesk','afsWorkspaceStation','afsWorkspaceDealer','afsDealerAppointment','afsDecorationCompany','afsServiceItem','afsProductBundle','afsDealerStoreContext','afsDealerCustomerInput','afsDealerPrivacyConsent')
GROUP BY mo.id,m.code,mo.code,mo.name,mo.enable,mo.api_list
ORDER BY m.code,mo.ordinal,mo.code;

