e":"afsAntiDiversion","ordinal":2,"enable":1,"targetIsHide":1},{"code":"afsBarcodeException","name":"条码异常","path":"afterSales/antiDiversion/barcodeException","parentCode":"afsAntiDiversion","ordinal":3,"enable":1,"targetIsHide":1},{"code":"afsDiversionReview","name":"异常复核","path":"afterSales/antiDiversion/review","parentCode":"afsAntiDiversion","ordinal":4,"enable":1,"targetIsHide":1},{"code":"afsDiversionRule","name":"防窜货规则","path":"afterSales/antiDiversion/rule","parentCode":"afsAntiDiversion","ordinal":5,"enable":1,"targetIsHide":1},{"code":"afsMember","name":"会员档案","path":"afterSales/memberOperation/member","parentCode":"afsMemberOperation","ordinal":1,"enable":1,"targetIsHide":1},{"code":"afsMemberTag","name":"标签管理","path":"afterSales/memberOperation/tag","parentCode":"afsMemberOperation","ordinal":2,"enable":1,"targetIsHide":0},{"code":"afsMemberPush","name":"消息推送","path":"afterSales/memberOperation/push","parentCode":"afsMemberOperation","ordinal":3,"enable":1,"targetIsHide":1},{"code":"afsServiceSurvey","name":"评价标签配置","path":"afterSales/memberOperation/serviceSurvey","parentCode":"afsMemberOperation","ordinal":4,"enable":1,"targetIsHide":0},{"code":"afsProductSurvey","name":"产品问卷","path":"afterSales/memberOperation/productSurvey","parentCode":"afsMemberOperation","ordinal":5,"enable":1,"targetIsHide":1},{"code":"afsReport","name":"运营报表","path":"afterSales/dataCenter/report","parentCode":"afsDataCenter","ordinal":1,"enable":1,"targetIsHide":0},{"code":"afsDictionary","name":"字典管理","path":"afterSales/dataCenter/dictionary","parentCode":"afsDataCenter","ordinal":2,"enable":1,"targetIsHide":0},{"code":"afsDataJob","name":"数据任务","path":"afterSales/dataCenter/job","parentCode":"afsDataCenter","ordinal":3,"enable":1,"targetIsHide":1},{"code":"afsDownloadTask","name":"导入导出任务","path":"afterSales/downloadCenter/task","parentCode":"afsDownloadCenter","ordinal":1,"enable":1,"targetIsHide":1},{"code":"afsDownloadTemplate","name":"导入导出模板","path":"afterSales/downloadCenter/template","parentCode":"afsDownloadCenter","ordinal":2,"enable":1,"targetIsHide":0},{"code":"afsDownloadScene","name":"导入导出场景配置","path":"afterSales/downloadCenter/scene","parentCode":"afsDownloadCenter","ordinal":3,"enable":1,"targetIsHide":1},{"code":"afsConsumerSupportConfig","name":"客服渠道配置","path":"afterSales/customerService/supportChannel","parentCode":"afsCustomerService","ordinal":11,"enable":1,"targetIsHide":0},{"code":"afsNavigationAdministrator","name":"售后全菜单查看","path":"afterSales/access/administrator","parentCode":"afterSales","ordinal":100,"enable":1,"targetIsHide":1},{"code":"afsWorkspaceHeadquarters","name":"总部运营视角","path":"afterSales/access/headquarters","parentCode":"afterSales","ordinal":101,"enable":1,"targetIsHide":1},{"code":"afsWorkspaceServiceDesk","name":"客服作业视角","path":"afterSales/access/serviceDesk","parentCode":"afterSales","ordinal":102,"enable":1,"targetIsHide":1},{"code":"afsWorkspaceStation","name":"服务站作业视角","path":"afterSales/access/station","parentCode":"afterSales","ordinal":103,"enable":1,"targetIsHide":1},{"code":"afsWorkspaceDealer","name":"门店业务视角","path":"afterSales/access/dealer","parentCode":"afterSales","ordinal":104,"enable":1,"targetIsHide":1}]', '$[*]' COLUMNS (code VARCHAR(100) PATH '$.code', expected_name VARCHAR(100) PATH '$.name', expected_path VARCHAR(100) PATH '$.path', parent_code VARCHAR(100) PATH '$.parentCode' NULL ON EMPTY, expected_ordinal BIGINT PATH '$.ordinal' NULL ON EMPTY, expected_enable INT PATH '$.enable', expected_is_hide INT PATH '$.targetIsHide')) AS target
)
SELECT desired.code,CASE WHEN actual.id IS NULL THEN 'MISSING' ELSE 'DIFFERENT' END AS drift,desired.expected_name,actual.name AS actual_name,desired.expected_path,actual.path AS actual_path,desired.parent_code,actual_parent.code AS actual_parent_code,desired.expected_ordinal,actual.ordinal AS actual_ordinal,desired.expected_enable,actual.enable AS actual_enable,desired.expected_is_hide,actual.is_hide AS actual_is_hide
FROM desired
LEFT JOIN sys_module actual ON actual.code=desired.code AND actual.category_code='pc_web'
LEFT JOIN sys_module actual_parent ON actual_parent.id=actual.parent_id
WHERE actual.id IS NULL OR actual.name<>desired.expected_name OR actual.path<>desired.expected_path OR NOT (actual_parent.code<=>desired.parent_code) OR (desired.expected_ordinal IS NOT NULL AND actual.ordinal<>desired.expected_ordinal) OR actual.enable<>desired.expected_enable OR actual.is_hide<>desired.expected_is_hide
ORDER BY desired.code;
